import assert from "node:assert/strict";
import test from "node:test";
import { hashPassword, verifyPassword } from "../src/utils/password.js";

// Synthetic fixtures generated by @node-rs/argon2 2.2.2 before replacing it.
const legacyHashes = [
  {
    password: "legacy-password",
    encoded:
      "$argon2id$v=19$m=19456,t=2,p=1$dGVzdC1zYWx0LTE2Ynl0ZXM$M9ndicefOdcqlQ/tE6sBJdyfrVZkMTb9hJdqBmCguoY",
  },
  {
    password: "pássword-🔐",
    encoded:
      "$argon2id$v=19$m=19456,t=2,p=1$dGVzdC1zYWx0LTE2Ynl0ZXM$OYzjPtWuQ0o7BCByB3MYj51BPDpGx/C4RzWk1rJYz2M",
  },
  {
    password: "legacy-alternate",
    encoded:
      "$argon2id$v=19$m=4096,t=3,p=2$dGVzdC1zYWx0LTE2Ynl0ZXM$MrILSNsKxXay1MjolMhOyrjeVrAgnHqpDz/R5eHOB5SUsOClOBegk/omfzB6vnZu",
  },
];

test("existing native Argon2id hashes still accept only the correct password", async () => {
  for (const { password, encoded } of legacyHashes) {
    assert.equal(await verifyPassword(encoded, password), true);
    assert.equal(await verifyPassword(encoded, `${password}!`), false);
  }
});

test("new hashes retain Argon2id costs, random salts and Unicode passwords", async () => {
  const password = "pássword-🔐";
  const first = await hashPassword(password);
  const second = await hashPassword(password);
  assert.match(first, /^\$argon2id\$v=19\$m=19456,t=2,p=1\$/);
  assert.notEqual(first, second);
  assert.equal(await verifyPassword(first, password), true);
  assert.equal(await verifyPassword(second, password), true);
  assert.equal(await verifyPassword(first, "wrong-password"), false);
});

test("accounts without a password never authenticate", async () => {
  assert.equal(await verifyPassword(null, "unused-account-password"), false);
  assert.equal(await verifyPassword(null, "wrong-password"), false);
});

test("malformed stored hashes cannot authenticate", async () => {
  await assert.rejects(verifyPassword("invalid-hash", "legacy-password"));
});
